window.BHASHA_VOCAB_DICT = BHASHA_VOCAB_DICT;
window.STORY_VOCAB_MAP = STORY_VOCAB_MAP;

window.getVocabComparison = function(vocabInput, storyId) {
  if (storyId && STORY_VOCAB_MAP[storyId]) {
    return STORY_VOCAB_MAP[storyId];
  }
  let terms = [];
  if (Array.isArray(vocabInput)) {
    terms = vocabInput.map(x => typeof x === "string" ? x : (x.english || x.tamil || ""));
  } else if (typeof vocabInput === "string") {
    terms = vocabInput.split(",").map(s => s.trim()).filter(Boolean);
  }
  const results = [];
  const seen = new Set();
  terms.forEach(term => {
    const clean = term.toLowerCase().trim();
    if (!clean || seen.has(clean)) return;
    seen.add(clean);
    if (BHASHA_VOCAB_DICT[clean]) {
      results.push(BHASHA_VOCAB_DICT[clean]);
    } else {
      results.push({
        english: term,
        tamil: term,
        telugu: term,
        teluguSpeak: term,
        kannada: term,
        kannadaSpeak: term,
        hindi: term,
        hindiSpeak: term
      });
    }
  });
  return results;
};
